    private fun symbol(name: String, autoMirror: Boolean, pathData: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f,
            autoMirror = autoMirror,
        ).addPath(PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black)).build()
